import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

import '../config.dart';
import '../logger.dart';
import '../png.dart';
import '../process.dart';
import '../pub.dart';
import 'frame_job.dart';

/// The widget test `brandify frame` generates in the app's project. It
/// only calls into `package:brandify_flutter/frame.dart`, which owns the
/// app_deploy_screenshots adapter.
const frameRunnerSource = '''
// Generated by `brandify frame`. Do not edit; it is rewritten on every run.
import 'package:brandify_flutter/frame.dart';

void main() => brandifyFrameMain();
''';

/// `brandify frame`: writes the job, runs the generated widget test with
/// `flutter test` (on the host, no device), then checks every output exists
/// at its store slot's exact size.
class FrameRunner {
  FrameRunner({
    required this.config,
    required this.runner,
    required this.logger,
    this.flutter = 'flutter',
    this.timeout = const Duration(minutes: 20),
  });

  final BrandifyConfig config;
  final ProcessRunner runner;
  final Logger logger;
  final String flutter;
  final Duration timeout;

  String get workDir => p.join(config.root, 'build', 'brandify', 'frame');

  Future<List<FrameItem>> run(FrameJob job) async {
    // The framed folders being written belong to brandify: start clean so
    // stale images never leak into an upload.
    for (final dir in {for (final i in job.items) p.dirname(i.out)}) {
      final d = Directory(dir);
      if (d.existsSync() && p.isWithin(config.framedDir, dir)) d.deleteSync(recursive: true);
      d.createSync(recursive: true);
    }

    Directory(workDir).createSync(recursive: true);
    final jobFile = p.join(workDir, 'job.json');
    File(jobFile).writeAsStringSync(job.encode());
    final testFile = p.join(workDir, 'brandify_frame_test.dart');
    File(testFile).writeAsStringSync(frameRunnerSource);

    final args = [
      'test', p.relative(testFile, from: config.root), '--no-pub', //
      '--dart-define=BRANDIFY_FRAME_JOB=$jobFile',
    ];
    await ensurePackages(root: config.root, runner: runner, logger: logger, flutter: flutter);
    logger.info('framing ${job.items.length} screenshots');
    logger.detail('$flutter ${args.join(' ')}');
    final r = await runner.run(flutter, args, timeout: timeout, workingDirectory: config.root);
    final output = '${r.stdout}\n${r.stderr}';
    for (final l in const LineSplitter().convert(output)) {
      logger.detail(l);
    }
    if (r.exitCode != 0) {
      final tail = const LineSplitter().convert(output).where((l) => l.trim().isNotEmpty).toList();
      final hint = output.contains("package:brandify_flutter") &&
              (output.contains('Not found') || output.contains("Couldn't resolve"))
          ? '\nHint: add brandify_flutter to dev_dependencies in ${config.root}/pubspec.yaml.'
          : '';
      throw BrandifyException('`flutter test` (framing) failed (exit ${r.exitCode}).\n'
          '${tail.skip(tail.length > 40 ? tail.length - 40 : 0).map((l) => '  | $l').join('\n')}$hint');
    }

    for (final i in job.items) {
      final f = File(i.out);
      if (!f.existsSync()) {
        throw BrandifyException('[${i.device} ${i.locale}] framing wrote no ${p.relative(i.out)}.');
      }
      final size = pngSize(f.readAsBytesSync());
      if (size == null || size.width != i.slot.width || size.height != i.slot.height) {
        throw BrandifyException('[${i.device} ${i.locale}] ${p.relative(i.out)} is '
            '${size == null ? 'not a PNG' : '${size.width}×${size.height}'}, but '
            '${i.slot} needs ${i.slot.width}×${i.slot.height}.');
      }
    }
    final groups = <String, int>{};
    for (final i in job.items) {
      final k = '[${i.device} ${i.locale}] ${i.slot}';
      groups[k] = (groups[k] ?? 0) + 1;
    }
    groups.forEach((k, n) => logger.info('$k: $n framed'));
    return job.items;
  }
}
